save(427,dict(paragraphs=['Sankar Narayan Mallick writes poetry in Odia and English and works as a translator. Based in Bhubaneswar, he has also had a career in agricultural and rural development with NABARD. His translations include Pratibha Ray’s Odia stories in “Three Maestros”, published by Black Eagle Books in 2024.','Water carries both distance and desire in his poems here. “The Mariner and the Muse” moves between a solitary voyage and an imagined meeting, until a dolphin’s splash returns the sailor to the sea. In “The Moon and the Mirror”, the attempt to hold a reflection gives way to a quieter homecoming. Both poems leave room for longing that cannot be fully possessed.'],books=[dict(title='Three Maestros',detail='Stories by Pratibha Ray, translated from Odia by Sankar Narayan Mallick. Black Eagle Books, 2024.',url='https://books.google.com/books/about/Three_Maestros.html?id=PQD20AEACAAJ')],sources=[source('Kalinga Literary Festival — Sankar Narayan Mallick','https://kalingaliteraryfestival.com/speakers/sankar-narayan-mallick/','Opened festival biography: bilingual English/Odia writer, translation/editing and NABARD agricultural/rural-development career.'),source('Google Books — Three Maestros','https://books.google.com/books/about/Three_Maestros.html?id=PQD20AEACAAJ','Opened bibliographic record: Pratibha Ray, Black Eagle Books, 10 November 2024, 126 pages; indexed translator field and translator biography name Mallick and Bhubaneswar. ISBN 9781645606116.','opened_page_and_search_index')],identity_match='Exact full name, bilingual English/Odia writing and Bhubaneswar residence in book contributor biography match preserved capture. Festival biography corroborates literary work and NABARD career. Author and translator of Three Maestros carefully distinguished.',poems_read=[dict(id=646,title='The Mariner and the Muse',coverage='Entire original English poem read, from solitary Sisyphus-like journey to final exploration.',basis='Unnamed voyage; contrasted scholarly muse and wandering mariner; imagined library and meeting across a table; water-glass ripples, horizon, dolphin splash interrupting reverie.'),dict(id=802,title='The Moon and the Mirror',coverage='All four original English stanzas read.',basis='A small wish among many; river and elusive moon reflection; lonely interior, wordless protest, quiet return while music and moon continue.')],limitations=['No actual seafaring occupation or romantic biography inferred from poems.','Precise former job titles and current employment omitted; broad NABARD experience supported by festival biography.','She of the Sky appears in bookseller catalogues, but classification varies and full description was inaccessible; not labelled a poetry collection or added to shelf.'],research_leads=[dict(url='https://www.hatchards.co.uk/book/she-of-the-sky/sankar-narayan-mallick/9781645608516',finding='Indexed author, Black Eagle Books, 16 March 2026, 124 pages, ISBN 9781645608516. Direct open failed; genre not established.'),dict(url='https://www.ibs.it/she-of-sky-libro-inglese-sankar-narayan-mallick/e/9781645608516',finding='Indexed matching title/author/ISBN; catalogue classification differs from other listings. Omitted pending primary book inspection.')],next_action='Independent author/editor review of narrative and translator credit; optionally confirm She of the Sky genre from publisher/title page.'))
